SELECT id, name, type, price, img, abv, order_count FROM t_product
WHERE id IN
#{id}

SELECT p.id, p.name, p.type, p.price, p.img, p.abv, p.order_count FROM t_product p
ORDER BY p.price ASC, p.id ASC ORDER BY p.price DESC, p.id ASC ORDER BY p.name ASC, p.id ASC ORDER BY p.order_count DESC, p.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT id, name, type, price, img, abv, order_count
FROM t_product
WHERE id = #{id}

mapper.update:
UPDATE t_product
SET order_count = order_count + #{quantity}
WHERE id = #{productId}

mapper.select:
SELECT id, name, type, price, img, abv, order_count
FROM t_product
WHERE type = #{type}
  AND name != #{excludeName}
ORDER BY order_count DESC, id ASC
LIMIT #{n}
